    <h1>User index</h1>

    <table class=\"table\">
        <thead>
            <tr>
                <th>Id</th>
                <th>Email</th>
                <th>Roles</th>
                <th>Password</th>
                <th>actions</th>
            </tr>
        </thead>
        <tbody>
        {% for user in users %}
            <tr>
                <td>{{ user.id }}</td>
                <td>{{ user.email }}</td>
                <td>{{ user.roles ? user.roles|json_encode : \x27\x27 }}</td>
                <td>{{ user.password }}</td>
                <td>
                    <a href=\"{{ path(\x27app_m2_l_show\x27, {\x27id\x27: user.id}) }}\">show</a>
                    <a href=\"{{ path(\x27app_m2_l_edit\x27, {\x27id\x27: user.id}) }}\">edit</a>
                </td>
            </tr>
